      terms_fallback: false,
      terms_source: null,
      term_canonicals: [],
      theses: [],
      thesis_mode: false,
      konspekt_fragment: konspektFrag.text || '',
      konspekt_matched: konspektFrag.matched,
      transcript_fragment: '',
      transcript_matched: false,
      user_base: null,
      request_ready: false,
    };
  }

  const termCanonicals = resolved.terms.map((t) => t.canonical);
  const termsBlock = resolved.terms.length
    ? resolved.terms
        .map((t) => {
          const src = String(t.definition_source || '').toLowerCase() === 'textbook' ? 'учебник' : 'лекция';
          const note =
            src === 'учебник'
              ? ' [источник: учебник — не пиши «по лекции» / «лектор сказал»]'
              : '';
          return '- ' + t.canonical + ': ' + t.definition + note;
        })
        .join('\n')
    : '[пусто — пиши только по ТЕЗИСАМ; source_kind=thesis, term_canonical=null]';
  const thesesBlock = theses.length
    ? theses.map((t, i) => (i + 1) + '. ' + t).join('\n')
    : '[тезисы не извлечены из своей секции — опирайся только на блок этой подтемы]';
  const transcriptText = transcriptFrag.text
    || '[фрагмент не найден — опирайся только на конспект]';
  const usedPlotsBlock = (usedPlots || []).length
    ? (usedPlots || []).slice(0, 40).map((s) => '- ' + s).join('\n')
    : '[пусто]';
  const usedAnswersBlock = (usedTermAnswers || []).length
    ? (usedTermAnswers || []).slice(0, 40).map((s) => '- ' + s).join('\n')
    : '[пусто]';

  const user = [
    'ПОДТЕМА\n' + subtopic.ordinal + '. ' + subtopic.title,
    'ТЕЗИСЫ\n' + thesesBlock,
    'ТЕРМИНЫ\n' + termsBlock,
    'ФРАГМЕНТ КОНСПЕКТА\n' + konspektFrag.text,
    'ФРАГМЕНТ ТРАНСКРИПТА\n' + transcriptText,
    'УЖЕ_ИСПОЛЬЗОВАНО\nСюжеты:\n' + usedPlotsBlock + '\nПары фокус–ответ:\n' + usedAnswersBlock,
  ].join('\n\n');

  return {
    skip: false,
    skip_reason: null,
    terms_fallback: resolved.fallback,
    terms_source: resolved.source,
    term_canonicals: termCanonicals,
    theses,
    thesis_mode: thesisMode,
    own_section_text: ownSection.text,
    own_section_matched: ownSection.matched,
    konspekt_fragment: konspektFrag.text,
    konspekt_matched: konspektFrag.matched,
    transcript_fragment: transcriptText,
    transcript_matched: transcriptFrag.matched,
    user_base: user,
    request_ready: true,
  };
}
const C = $('Run — Init Constants').first().json.constants;
const src = $('LLM — Build Terms Request').first().json;
const L = $('Load — Lecture').first().json;
function parseDeepSeek(resp, C, src, step, promptVersion) {
  const r = resp || {};
  const choice = (r.choices && r.choices[0]) || {};
  const content = String((choice.message && choice.message.content) || '');
  const u = r.usage || {};
  const hit = Number(u.prompt_cache_hit_tokens != null
    ? u.prompt_cache_hit_tokens
    : ((u.prompt_tokens_details && u.prompt_tokens_details.cached_tokens) || 0)) || 0;
  let miss = u.prompt_cache_miss_tokens != null ? Number(u.prompt_cache_miss_tokens) : null;
  const promptTokens = Number(u.prompt_tokens != null ? u.prompt_tokens : ((miss || 0) + hit)) || 0;
  if (miss == null || !Number.isFinite(miss)) miss = Math.max(promptTokens - hit, 0);
  const completion = Number(u.completion_tokens) || 0;
  const P = C.prices_usd_per_1m;
  const costExact = (miss * P.miss + hit * P.hit + completion * P.out) / 1e6;
  return {
    content,
    finish_reason: choice.finish_reason || null,
    cost_exact: costExact,
    usage_row: {
      lecture_id: src.lecture_id,
      job_id: src.job_id,
      workflow_name: C.workflow_name,
      workflow_version: C.workflow_version,
      model: r.model || C.llm_model,
      prompt_tokens: promptTokens,
      completion_tokens: completion,
      cost_usd: Number(costExact.toFixed(6)),
      prompt_version: promptVersion,
      prompt_cache_hit_tokens: hit,
      step,
    },
  };
}
const p = parseDeepSeek(items[0].json, C, src, 'terms', C.prompt_versions.terms);

function parseJson(text) {
  let t = String(text || '').trim();
  const m = t.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/);
  if (m) t = m[1];
  try {
    return { value: JSON.parse(t) };
  } catch (e) {
    const a = t.indexOf('{');
    const b = t.lastIndexOf('}');
    if (a >= 0 && b > a) {
      try {
        return { value: JSON.parse(t.slice(a, b + 1)) };
      } catch (e2) {
        /* fall through */
      }
    }
    return { error: 'invalid_json' };
  }
}

const result = {
  lecture_id: src.lecture_id,
  job_id: src.job_id,
  usage_row: p.usage_row,
  cost_exact: p.cost_exact,
  finish_reason: p.finish_reason,
  transcript_truncated: src.transcript_truncated,
  ok: false,
  error_message: null,
  subtopics: [],
  terms: [],
