    subtopicIndex,
    subtopicCount,
  });
  // Context fragment may include ±1 neighbour; theses come ONLY from own ## section.
  const konspektFrag = pickKonspektFragment(
    konspektMd,
    subtopic.title,
    resolved.terms,
    konspektMax,
    { subtopicIndex, subtopicCount },
