        .join('\n')
    : '[пусто — пиши только по ТЕЗИСАМ; source_kind=thesis, term_canonical=null]';
  const thesesBlock = theses.length
    ? theses.map((t, i) => (i + 1) + '. ' + t).join('\n')
    : '[тезисы не извлечены из своей секции — опирайся только на блок этой подтемы]';
  const transcriptText = transcriptFrag.text
    || '[фрагмент не найден — опирайся только на конспект]';
  const usedPlotsBlock = (usedPlots || []).length
    ? (usedPlots || []).slice(0, 40).map((s) => '- ' + s).join('\n')
    : '[пусто]';
  const usedAnswersBlock = (usedTermAnswers || []).length
    ? (usedTermAnswers || []).slice(0, 40).map((s) => '- ' + s).join('\n')
    : '[пусто]';

  const user = [
    'ПОДТЕМА\n' + subtopic.ordinal + '. ' + subtopic.title,
    'ТЕЗИСЫ\n' + thesesBlock,
    'ТЕРМИНЫ\n' + termsBlock,
    'ФРАГМЕНТ КОНСПЕКТА\n' + konspektFrag.text,
    'ФРАГМЕНТ ТРАНСКРИПТА\n' + transcriptText,
    'УЖЕ_ИСПОЛЬЗОВАНО\nСюжеты:\n' + usedPlotsBlock + '\nПары фокус–ответ:\n' + usedAnswersBlock,
  ].join('\n\n');

  return {
    skip: false,
    skip_reason: null,
    terms_fallback: resolved.fallback,
    terms_source: resolved.source,
    term_canonicals: termCanonicals,
    theses,
    thesis_mode: thesisMode,
    own_section_text: ownSection.text,
    own_section_matched: ownSection.matched,
    konspekt_fragment: konspektFrag.text,
    konspekt_matched: konspektFrag.matched,
    transcript_fragment: transcriptText,
    transcript_matched: transcriptFrag.matched,
    user_base: user,
    request_ready: true,
  };
}
const C = $('Run — Init Constants').first().json.constants;
const L = $('Load — Lecture').first().json;
const M = items[0].json;
const SYSTEM = "Ты дозаполняешь определения терминов одной лекции. Источник — только блоки этого сообщения. Не добавляй факты из других лекций и из общих знаний.\n\nВход:\nТЕРМИНЫ_БЕЗ_ОПРЕДЕЛЕНИЯ — список canonical (и aliases), у которых definition пуст или бракован\nФРАГМЕНТ КОНСПЕКТА\nФРАГМЕНТ ТРАНСКРИПТА\n\nПравила:\n- definition — только законченная формулировка смысла термина: одно-два предложения «X — это …».\n- Бери формулировку, только если она явно есть в конспекте или транскрипте этой лекции.\n- Если в тексте нет определения — definition = null. Не выводи «очевидное» из общих знаний.\n- Запрещено возвращать: обрывки цифр и процентов без смысла термина; цитату из середины абзаца; тезис/вывод лекции вместо определения; одно слово-ярлык без пояснения.\n- life_example — только если есть definition и во фрагменте есть бытовая иллюстрация; иначе null.\n- `[неразборчиво]` не раскрывай.\n- Не добавляй новые термины. canonical копируй как во входе.\n\nОтвет — один JSON без Markdown:\n\n{\"terms\":[{\"canonical\":\"...\",\"definition\":null,\"life_example\":null}]}";
const cpt = C.chars_per_token || 2;
const est = (s) => Math.ceil(String(s || '').length / cpt);
const empty = M.empty_definitions || [];
const termsBlock = empty.map((t) => {
  const al = (t.aliases || []).length ? ' (' + t.aliases.join(', ') + ')' : '';
  return '- ' + t.canonical + al;
}).join('\n');
const user = [
  'ТЕРМИНЫ_БЕЗ_ОПРЕДЕЛЕНИЯ\n' + termsBlock,
  'ФРАГМЕНТ КОНСПЕКТА\n' + String(L.konspekt_md || '').slice(0, 12000),
